                        stack.append((yy, xx))
            top, left = min(y for y, x in cells), min(x for y, x in cells)
            shape = [(y-top, x-left) for y, x in cells]
            height = max(y for y, x in shape) + 1
            width = max(x for y, x in shape) + 1
            objs.append((left, color, shape, height, width))

    objs.sort()
    out = [[0] * w for _ in range(h)]
    if not objs:
        return out
    _, _, _, first_h, first_w = objs[0]
    row = col = 0
    for i, (_, color, shape, _, _) in enumerate(objs):
